#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007;

struct Mod {
    ll v;
    Mod(ll n = 0) : v((n % MOD + MOD) % MOD) {}
    operator ll() const { return v; }
};

Mod operator+(const Mod& a, const Mod& b) { return Mod((a.v + b.v) % MOD); }
Mod operator-(const Mod& a, const Mod& b) { return Mod((a.v - b.v + MOD) % MOD); }
Mod operator*(const Mod& a, const Mod& b) { return Mod((a.v * b.v) % MOD); }
Mod& operator+=(Mod& a, const Mod& b) { return a = a + b; }
Mod& operator-=(Mod& a, const Mod& b) { return a = a - b; }
Mod& operator*=(Mod& a, const Mod& b) { return a = a * b; }

Mod modPow(Mod b, int e) {
    Mod r(1);
    while (e) {
        if (e & 1) r *= b;
        b *= b;
        e >>= 1;
    }
    return r;
}

Mod modInv(const Mod& a) { return modPow(a, MOD - 2); }
Mod operator/(const Mod& a, const Mod& b) { return a * modInv(b); }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<vector<Mod>> pers(6, vector<Mod>(6));

    int N;
    cin >> N;
    int s = 3 - (N + 1) / 2;

    for (int i = 0; i < s; ++i) pers[i][i] = Mod(1);

    for (int i = s; i < s + N; ++i) {
        for (int j = s; j < s + N; ++j) {
            int p;
            cin >> p;
            pers[i][j] = Mod(p) / Mod(100);
        }
    }

    for (int i = s + N; i < 6; ++i) pers[i][i] = Mod(1);

    // Generate all permutations of {0,0,0,1,1,1}
    vector<int> v = {0, 0, 0, 1, 1, 1};
    map<int, int> permMap;
    int id = 0;
    do {
        int mask = 0;
        for (int k = 0; k < 6; ++k) {
            if (v[k]) mask |= (1 << k);
        }
        permMap[mask] = id++;
    } while (next_permutation(v.begin(), v.end()));

    // Solve function
    auto solve = [&](int offset) -> vector<Mod> {
        vector<Mod> res(1 << 20, Mod(0));
        for (int m = 0; m < (1 << 18); ++m) {
            vector<vector<int>> h(3, vector<int>(6, 0));
            Mod p(1);
            for (int i = 0; i < 3; ++i) {
                for (int j = 0; j < 6; ++j) {
                    int idx = i * 6 + j;
                    if (m & (1 << idx)) {
                        h[i][j] = 1;
                        p *= pers[offset + i][j];
                    } else {
                        p *= (Mod(1) - pers[offset + i][j]);
                    }
                }
            }
            int f = 0;
            for (int i = 0; i < 6; ++i) {
                if (!h[0][i]) continue;
                for (int j = 0; j < 6; ++j) {
                    if (!h[1][j]) continue;
                    if (i == j) continue;
                    for (int k = 0; k < 6; ++k) {
                        if (!h[2][k]) continue;
                        if (i == k || j == k) continue;
                        int anum = (1 << i) ^ (1 << j) ^ (1 << k);
                        f |= (1 << permMap[anum]);
                    }
                }
            }
            res[f] += p;
        }
        return res;
    };

    auto up = solve(0);
    auto dn = solve(3);

    // FWT-style summation
    for (int b = 1; b < (1 << 20); b <<= 1) {
        for (int i = 0; i < (1 << 20); ++i) {
            if (!(i & b)) dn[i ^ b] += dn[i];
        }
    }

    Mod ans(0);
    for (int m = 0; m < (1 << 20); ++m) {
        if (up[m].v == 0) continue;
        int need = 0;
        for (int x = 0; x < 20; ++x) {
            if (m & (1 << x)) need |= (1 << (19 - x));
        }
        int comp = ((1 << 20) - 1) ^ need;
        ans += up[m] * (Mod(1) - dn[comp]);
    }

    cout << ans.v << '\n';
    return 0;
}
